import{_ as l,a0 as s,w as r,s as p,I as a,x as e,a1 as o,A as i,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"GNOME 雄心勃勃的窗口管理改革 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME 雄心勃勃的窗口管理改革 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME 雄心勃勃的窗口管理改革 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME 雄心勃勃的窗口管理改革 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230728.1 ⭐️⭐️ GNOME’s Ambitious Window Management Overhaul","title":"GNOME 雄心勃勃的窗口管理改革","tag":"202308","desc":""},"relativePath":"202308/20230728.1 ⭐️⭐️ GNOME’s Ambitious Window Management Overhaul.md","filePath":"[post].md"}'),d={name:"202308/20230728.1 ⭐️⭐️ GNOME’s Ambitious Window Management Overhaul.md"};function u(g,t,b,f,M,w){const n=s("Link");return r(),p("div",null,[t[21]||(t[21]=a("h1",{id:"gnome-雄心勃勃的窗口管理改革",tabindex:"-1"},[e("GNOME 雄心勃勃的窗口管理改革 "),a("a",{class:"header-anchor",href:"#gnome-雄心勃勃的窗口管理改革","aria-label":"Permalink to “GNOME 雄心勃勃的窗口管理改革”"},"​")],-1)),t[22]||(t[22]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/09/104949la7f2nqen7qq2ftt.jpg",alt:""})],-1)),t[23]||(t[23]=a("blockquote",null,[a("p",null,"厭倦了窗口混亂和手動調整？ GNOME 正在集體討論一個自動化且用户友好的窗口管理系統。這是你需要了解的情況。")],-1)),t[24]||(t[24]=a("p",null,"窗口管理是桌面計算的一個重要方面，幾十年來一直是人們着迷和探索的話題。然而，儘管進行了多次嘗試，仍然沒有人能夠破解完美的窗口管理解決方案的密碼。GNOME 開發人員現在開始致力於徹底改變窗口管理，旨在提高生產力和用户體驗。",-1)),a("p",null,[t[1]||(t[1]=e("GNOME 開發人員 Tobias Bernard 發表了一篇 ",-1)),o(n,{href:"https://blogs.gnome.org/tbernard/2023/07/26/rethinking-window-management/"},{default:i(()=>[...t[0]||(t[0]=[e("詳細的文章",-1)])]),_:1}),t[2]||(t[2]=e("，介紹了開發人員如何考慮為未來創新 GNOME 桌面。",-1))]),t[25]||(t[25]=m('<h3 id="傳統窗口系統的挑戰" tabindex="-1">傳統窗口系統的挑戰 <a class="header-anchor" href="#傳統窗口系統的挑戰" aria-label="Permalink to “傳統窗口系統的挑戰”">​</a></h3><p>傳統的窗口系統為我們提供了很好的服務，允許應用生成可以手動移動和調整大小的矩形窗口。然而，隨着窗口數量和尺寸的增加，問題開始出現。重疊的窗口很快就會變得一團糟，使得在不隱藏其他應用的情況下訪問特定應序變得困難。最大化窗口可能會遮擋桌面上的其他所有內容，從而導致混亂和效率低下。</p><p>多年來，各種操作系統引入了工作區、任務欄和切換器等解決方法來處理這些問題。然而，窗口管理的核心問題仍未解決。特別是對於兒童和老年人等計算機新手來説，手動排列窗口可能會很麻煩且乏味。</p><h3 id="引入平鋪窗口管理器" tabindex="-1">引入平鋪窗口管理器 <a class="header-anchor" href="#引入平鋪窗口管理器" aria-label="Permalink to “引入平鋪窗口管理器”">​</a></h3><p>平鋪窗口管理器提供了防止窗口重疊的替代解決方案。雖然它們在某些情況下運行良好，但也有其侷限性。平鋪窗口可能會導致效率低下，因為應用通常是針對特定尺寸和縱橫比設計的。此外，這些窗口管理器缺乏關於窗口內容和上下文的知識，需要額外的手動調整，並違背了簡化工作流程的目的。更不用説記住很多鍵盤快捷鍵了。</p><h3 id="gnome-當前的平鋪功能" tabindex="-1">GNOME 當前的平鋪功能 <a class="header-anchor" href="#gnome-當前的平鋪功能" aria-label="Permalink to “GNOME 當前的平鋪功能”">​</a></h3><p>GNOME 已經在 GNOME 3 系列中嘗試了基本的平鋪功能。然而，現有的實現有一些侷限性。這是一個手動過程，僅支持兩個窗口，缺乏複雜佈局的可擴展性，並且不會將平鋪窗口分組到窗口棧中。</p><h3 id="窗口管理的新願景" tabindex="-1">窗口管理的新願景 <a class="header-anchor" href="#窗口管理的新願景" aria-label="Permalink to “窗口管理的新願景”">​</a></h3><p>該團隊提出了一種新的窗口管理方法，重點關注符合用户期望和需求的自動化系統。他們的概念涉及窗口的三種潛在佈局狀態：馬賽克、邊緣平鋪和浮動。</p><p>馬賽克模式將成為默認行為，根據用户偏好和可用屏幕空間智能定位窗口並調整窗口大小。隨着新窗口的打開，現有窗口將進行調整以適應新來者。如果窗口不適合當前佈局，它將被放置在自己的工作區中。當屏幕接近佈滿時，窗口將自動平鋪。</p><p>用户還可以通過將窗口拖動到現有窗口或空白區域上來手動平鋪窗口。該系統提供了靈活性和便利性，使其更容易高效地執行多任務。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/07/mosaic-open-close.webm" alt="mosaic-open-close (Video credit: GNOME)"></p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/07/mosaic-maximize.webm" alt="mosaic-maximize (Video credit: GNOME)"></p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/07/mosaic-vertical-tile.webm" alt="mosaic-vertical-tile (Video credit: GNOME)"></p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/07/mosaic-tile2.webm" alt="mosaic-tile2 (Video credit: GNOME)"></p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/07/mosaic-tile3.webm" alt="mosaic-tile3 (Video credit: GNOME)"></p><h3 id="維護用户友好的浮動窗口" tabindex="-1">維護用户友好的浮動窗口 <a class="header-anchor" href="#維護用户友好的浮動窗口" aria-label="Permalink to “維護用户友好的浮動窗口”">​</a></h3><p>雖然平鋪提供了多種好處，但 GNOME 開發人員明白，總會有用户更喜歡手動定位窗口的情況。因此，經典的浮動行為仍然適用於這些特定情況，但隨着新的馬賽克系統的引入，它可能不太常見。</p><h3 id="利用窗口元數據增強性能" tabindex="-1">利用窗口元數據增強性能 <a class="header-anchor" href="#利用窗口元數據增強性能" aria-label="Permalink to “利用窗口元數據增強性能”">​</a></h3><p>GNOME 旨在優化平鋪體驗，以從窗口收集有關其內容的更多信息。這包括窗口的最大所需尺寸以及應用最佳運行的理想尺寸範圍等詳細信息。通過使用這些元數據，系統可以定製窗口布局以滿足用户的需求，從而提高整體可用性。</p><h3 id="展望未來" tabindex="-1">展望未來 <a class="header-anchor" href="#展望未來" aria-label="Permalink to “展望未來”">​</a></h3><p>雖然 GNOME 開發人員對這個新的窗口管理方向感到興奮，但他們也承認與這種新穎方法相關的風險。他們計劃進行用户研究以驗證他們的假設並完善交互。儘管沒有具體的實施時間表，但該項目可能會跨越多個開發週期，併成為 GNOME 46 或更高版本的一部分。</p><p>截至發佈此內容時，還沒有草案合併請求，你可以參與其中並提供反饋。</p>',23)),a("p",null,[t[4]||(t[4]=e("參考自 ",-1)),o(n,{href:"https://blogs.gnome.org/tbernard/2023/07/26/rethinking-window-management/"},{default:i(()=>[...t[3]||(t[3]=[e("Tobias 的Blog",-1)])]),_:1}),t[5]||(t[5]=e("。",-1))]),t[26]||(t[26]=a("p",null,[a("em",null,"（題圖：MJ/04285b09-a074-4f6f-a32e-ae5af06f1d1f）")],-1)),t[27]||(t[27]=a("hr",null,null,-1)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"https://debugpointnews.com/gnome-window-management-proposal/"},{default:i(()=>[...t[6]||(t[6]=[e("https://debugpointnews.com/gnome-window-management-proposal/",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("作者：",-1)),o(n,{href:"https://debugpointnews.com/author/dpicubegmail-com/"},{default:i(()=>[...t[8]||(t[8]=[e("arindam",-1)])]),_:1}),t[13]||(t[13]=e(" 選題：",-1)),o(n,{href:"https://github.com/lkxed/"},{default:i(()=>[...t[9]||(t[9]=[e("lkxed",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[10]||(t[10]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const G=l(d,[["render",u]]);export{E as __pageData,G as default};
